'use client'

import type { FormEvent } from 'react'
import { useState } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { ArrowRight, Loader2, LockKeyhole, Mail, Sparkles, UserRound } from 'lucide-react'
import { motion } from 'motion/react'
import { authClient } from '../../lib/auth-client'
import { Button } from '../ui/button'
import { Input } from '../ui/input'

type AuthMode = 'login' | 'signup'

type AuthPageProps = {
  mode: AuthMode
}

const authCopy = {
  login: {
    eyebrow: 'Secure workspace',
    title: 'Welcome back',
    action: 'Login',
    switchText: 'New to the desk?',
    switchAction: 'Create account',
    switchTo: '/signup',
  },
  signup: {
    eyebrow: 'Create workspace',
    title: 'Start pricing smarter',
    action: 'Sign up',
    switchText: 'Already have an account?',
    switchAction: 'Login',
    switchTo: '/login',
  },
} satisfies Record<AuthMode, Record<string, string>>

export function AuthPage({ mode }: AuthPageProps) {
  const router = useRouter()
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)
  const copy = authCopy[mode]

  function getRedirectTo() {
    const next = new URLSearchParams(window.location.search).get('next')
    return next?.startsWith('/') ? next : '/app'
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    setError('')
    setIsSubmitting(true)

    try {
      const redirectTo = getRedirectTo()
      const response =
        mode === 'signup'
          ? await authClient.signUp.email({
              name: name.trim() || email.split('@')[0],
              email: email.trim(),
              password,
              callbackURL: redirectTo,
            })
          : await authClient.signIn.email({
              email: email.trim(),
              password,
              callbackURL: redirectTo,
            })

      if (response.error) {
        setError(response.error.message || 'Authentication failed.')
        return
      }

      router.replace(redirectTo)
    } catch (caughtError) {
      setError(
        caughtError instanceof Error
          ? caughtError.message
          : 'Authentication service is unavailable.',
      )
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <main className="premium-stage relative min-h-screen overflow-hidden px-4 py-6 text-slate-950 sm:px-6 lg:px-8">
      <div className="pointer-events-none absolute inset-0 bg-[linear-gradient(125deg,rgba(238,77,45,0.16)_0%,rgba(255,255,255,0)_37%,rgba(6,182,212,0.16)_72%,rgba(16,185,129,0.12)_100%)]" />
      <div className="relative z-10 mx-auto grid min-h-[calc(100vh-3rem)] w-full max-w-6xl items-center gap-10 lg:grid-cols-[1.05fr_0.95fr]">
        <motion.section
          initial={{ opacity: 0, x: -24 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.55, ease: [0.22, 1, 0.36, 1] }}
          className="hidden lg:block"
        >
          <div className="mb-6 inline-flex items-center gap-2 rounded-lg border border-white/70 bg-white/70 px-3 py-2 text-xs font-black uppercase tracking-[0.18em] text-shopee shadow-soft backdrop-blur-md">
            <Sparkles className="h-4 w-4" />
            Shopee Pricing Desk
          </div>
          <h1 className="max-w-2xl text-5xl font-black leading-[0.95] text-slate-950">
            Shopee Pricing Desk
          </h1>
          <p className="mt-5 max-w-xl text-base font-medium leading-7 text-slate-600">
            Secure workspace for high-ticket electronics retail pricing.
          </p>
          <div className="mt-8 grid max-w-xl grid-cols-3 gap-3">
            {['Margin', 'Fees', 'Revenue'].map((item, index) => (
              <motion.div
                key={item}
                initial={{ opacity: 0, y: 14 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.15 + index * 0.08, duration: 0.45 }}
                className="rounded-lg border border-white/70 bg-white/65 p-4 shadow-soft backdrop-blur-md"
              >
                <p className="text-xs font-black uppercase tracking-wide text-slate-500">
                  0{index + 1}
                </p>
                <p className="mt-3 text-sm font-black text-slate-950">{item}</p>
              </motion.div>
            ))}
          </div>
        </motion.section>

        <motion.section
          initial={{ opacity: 0, y: 24, scale: 0.98 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, y: -18, scale: 0.98 }}
          transition={{ duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
          className="mx-auto w-full max-w-md rounded-lg border border-white/75 bg-white/78 p-5 shadow-glass backdrop-blur-2xl sm:p-6"
        >
          <div className="mb-7">
            <p className="text-xs font-black uppercase tracking-[0.2em] text-shopee">
              {copy.eyebrow}
            </p>
            <h2 className="mt-2 text-3xl font-black tracking-tight text-slate-950">
              {copy.title}
            </h2>
          </div>

          <form className="space-y-4" onSubmit={handleSubmit}>
            {mode === 'signup' ? (
              <label className="block space-y-2">
                <span className="text-sm font-bold text-slate-700">Name</span>
                <span className="relative block">
                  <UserRound className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
                  <Input
                    value={name}
                    onChange={(event) => setName(event.target.value)}
                    className="pl-10"
                    autoComplete="name"
                  />
                </span>
              </label>
            ) : null}

            <label className="block space-y-2">
              <span className="text-sm font-bold text-slate-700">Email</span>
              <span className="relative block">
                <Mail className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
                <Input
                  type="email"
                  value={email}
                  onChange={(event) => setEmail(event.target.value)}
                  className="pl-10"
                  autoComplete="email"
                  required
                />
              </span>
            </label>

            <label className="block space-y-2">
              <span className="text-sm font-bold text-slate-700">Password</span>
              <span className="relative block">
                <LockKeyhole className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
                <Input
                  type="password"
                  value={password}
                  onChange={(event) => setPassword(event.target.value)}
                  className="pl-10"
                  autoComplete={mode === 'signup' ? 'new-password' : 'current-password'}
                  minLength={8}
                  required
                />
              </span>
            </label>

            {error ? (
              <motion.p
                initial={{ opacity: 0, y: -6 }}
                animate={{ opacity: 1, y: 0 }}
                className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm font-semibold text-red-700"
              >
                {error}
              </motion.p>
            ) : null}

            <Button type="submit" size="lg" className="w-full" disabled={isSubmitting}>
              {isSubmitting ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
              {copy.action}
              {!isSubmitting ? <ArrowRight className="h-4 w-4" /> : null}
            </Button>
          </form>

          <p className="mt-6 text-center text-sm font-semibold text-slate-500">
            {copy.switchText}{' '}
            <Link
              className="font-black text-shopee transition-colors hover:text-shopee-dark"
              href={copy.switchTo}
            >
              {copy.switchAction}
            </Link>
          </p>
        </motion.section>
      </div>
    </main>
  )
}
